package in.tallybridge.app;import android.app.PendingIntent;import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;public final class QuickDockWidget extends AppWidgetProvider{private static PendingIntent p(Context c,int r,Intent i){return PendingIntent.getActivity(c,r,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.quick_dock_widget);v.setOnClickPendingIntent(R.id.quick_dock_brand,p(c,7100+id,new Intent(c,MainActivity.class).setAction(MainActivity.ACTION_HOME)));v.setOnClickPendingIntent(R.id.quick_dock_order,p(c,7200+id,new Intent(c,OrdersActivity.class).setAction(OrdersActivity.ACTION_NEW)));v.setOnClickPendingIntent(R.id.quick_dock_gsm,p(c,7300+id,new Intent(c,GsmCalculatorActivity.class)));v.setOnClickPendingIntent(R.id.quick_dock_proforma,p(c,7400+id,new Intent(c,MainActivity.class).setAction(MainActivity.ACTION_NEW_PROFORMA)));m.updateAppWidget(id,v);}}}
